  m.cameras=new CheeseCamera[4];for(int i=0;i<4;i++){var camera=new GameObject("Cheese chase camera "+(i+1));var cam=camera.AddComponent<Camera>();cam.fieldOfView=68;cam.farClipPlane=600;cam.nearClipPlane=.18f;cam.backgroundColor=new Color(.4f,.6f,.7f);cam.clearFlags=CameraClearFlags.Skybox;var c=camera.AddComponent<CheeseCamera>();c.match=m;c.view=cam;c.slot=i;var target=new GameObject("Stable world-up camera target "+i).transform;c.target=target;var aim=new GameObject("Downhill camera look "+i).transform;c.aim=aim;var rig=new GameObject("Cinemachine chase rig "+i).AddComponent<CinemachineVirtualCamera>();rig.Follow=target;rig.LookAt=aim;rig.m_Lens.FieldOfView=68;var follow=rig.AddCinemachineComponent<CinemachineTransposer>();follow.m_BindingMode=CinemachineTransposer.BindingMode.LockToTargetWithWorldUp;follow.m_FollowOffset=new Vector3(0,6,-9);follow.m_XDamping=follow.m_YDamping=follow.m_ZDamping=.2f;var composer=rig.AddCinemachineComponent<CinemachineComposer>();composer.m_HorizontalDamping=composer.m_VerticalDamping=.15f;composer.m_DeadZoneWidth=composer.m_DeadZoneHeight=0;var avoid=rig.gameObject.AddComponent<CinemachineCollider>();avoid.m_CollideAgainst=1;avoid.m_CameraRadius=.5f;avoid.m_DampingWhenOccluded=.1f;c.rig=rig;c.follow=follow;m.cameras[i]=c;camera.tag=i==0?"MainCamera":"Untagged";}
