mmediate(dayProfile);}day.DayNightProfile=dayAsset;adapter.precipitation=weather.GetComponentInChildren<WeatherMakerPrecipitationManagerScript>(true);foreach(var p in new[]{adapter.precipitation.RainScript,adapter.precipitation.SnowScript}){p.BaseEmissionRate=600;p.BaseEmissionRateSecondary=70;p.BaseMistEmissionRate=15;p.CollisionEnabled=false;}
  foreach(var cloud in weather.GetComponentsInChildren<WeatherMakerFullScreenCloudsScript>(true))cloud.enabled=false;foreach(var fog in weather.GetComponentsInChildren<WeatherMakerFullScreenFogScript>(true))fog.enabled=false;foreach(var a in weather.GetComponentsInChildren<AudioListener>(true))UnityEngine.Object.DestroyImmediate(a);var sun=new GameObject("Race daylight").AddComponent<Light>();sun.type=LightType.Directional;sun.shadows=LightShadows.Soft;sun.intensity=2;sun.transform.rotation=Quaternion.Euler(40,-25,0);adapter.sun=sun;adapter.ambience=Loop(root,"Assets/TruckCornhole/Audio/Wind.wav");m.weather=adapter;
  m.sheep=new CheeseSheep[36];var hazard=new GameObject("Explosive sheep");var hs=hazard.AddComponent<CheeseSheep>();var model=new GameObject("Genuine sheep model assign here");model.transform.SetParent(hazard.transform);hs.modelSlot=model.transform;var sphere=hazard.AddComponent<SphereCollider>();sphere.radius=1.1f;var sheepModel=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Art/Sheep/SheepV5.fbx");if(sheepModel==null)throw new Exception("SheepV5 model missing");var instance=(GameObject)PrefabUtility.InstantiatePrefab(sheepModel,model.transform);var renderers=instance.GetComponentsInChildren<Renderer>();var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);float scale=2.7f/Mathf.Max(bounds.size.x,bounds.size.z);instance.transform.localScale=Vector3.one*scale;instance.transform.localPosition=new Vector3(-bounds.center.x*scale,-bounds.min.y*scale-.7f,-bounds.center.z*scale);var wool=Mat("Haberdashery sheep wool",Color.white,.15f);wool.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Art/Sheep/SheepBody.png");foreach(var r in renderers)r.sharedMaterial=wool;hs.warning=Primitive("Explosive red collar",PrimitiveType.Cylinder,hazard.transform,new Vector3(0,.25f,0),new Vector3(.65f,.12f,.65f),red);PrefabUtility.SaveAsPrefabAsset(hazard,Root+"Prefabs/ExplosiveSheep.prefab");UnityEngine.Object.DestroyImmediate(hazard);var hp=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Prefabs/ExplosiveSheep.prefab");for(int i=0;i<m.sheep.Length;i++){var h=(GameObject)PrefabUtility.InstantiatePrefab(hp);m.sheep[i]=h.GetComponent<CheeseSheep>();m.sheep[i].match=m;h.SetActive(false);}
