 static Terrain Terrain(CheeseMatch m){string path=Root+"Terrain/Cheese hill.asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(path);if(data==null){data=new TerrainData();AssetDatabase.CreateAsset(data,path);}data.heightmapResolution=257;data.size=new Vector3(140,500,360);var h=new float[257,257];for(int z=0;z<257;z++)for(int x=0;x<257;x++)h[z,x]=CheeseRules.Height(x/256f*140-70,z/256f*360-20)/500;data.SetHeights(0,0,h);data.alphamapResolution=128;var grass=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer");var mud=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/3D Haven/Path Painter II/Editor/Demo/Terrains/DocsTerrain/TerrainLayers/stdMudRocky.terrainlayer");if(grass==null||mud==null)throw new Exception("Installed Vista grass / Path Painter mud layer missing");data.terrainLayers=new[]{grass,mud};var splat=new float[128,128,2];for(int z=0;z<128;z++)for(int x=0;x<128;x++){float v=Mathf.SmoothStep(0,1,(z/127f*360-20-214)/20);splat[z,x,0]=1-v;splat[z,x,1]=v;}data.SetAlphamaps(0,0,splat);var terrain=UnityEngine.Terrain.CreateTerrainGameObject(data).GetComponent<UnityEngine.Terrain>();terrain.name="Single seamless 50-degree grassy hill and muddy runout";terrain.transform.position=new Vector3(-70,0,-20);terrain.heightmapPixelError=8;terrain.basemapDistance=600;terrain.drawInstanced=true;var material=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Hill terrain.mat");if(material==null){material=new Material(Shader.Find("Universal Render Pipeline/Terrain/Lit"));AssetDatabase.CreateAsset(material,Root+"Materials/Hill terrain.mat");}terrain.materialTemplate=material;
  // Reuse installed lightweight vegetation without introducing another terrain generator.
  var plant=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Grass_01.prefab");var rng=new System.Random(479);if(plant!=null)for(int i=0;i<110;i++){float x=(float)(rng.NextDouble()*110-55),z=(float)(rng.NextDouble()*145+22);var p=(GameObject)PrefabUtility.InstantiatePrefab(plant);PrefabUtility.UnpackPrefabInstance(p,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);p.transform.position=CheeseRules.Surface(x,z);p.transform.localScale=Vector3.one*.5f;foreach(var c in p.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);}return terrain;
