 static CheeseTruck Truck(CheeseMatch m,int i,PhysicsMaterial contact,Material dark){var g=new GameObject("Racer "+i);g.layer=2;var b=g.AddComponent<Rigidbody>();b.mass=48;b.centerOfMass=new Vector3(0,-.07f,0);b.interpolation=RigidbodyInterpolation.Interpolate;b.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;b.solverIterations=10;b.solverVelocityIterations=4;b.maxLinearVelocity=48;b.maxAngularVelocity=18;b.maxDepenetrationVelocity=8;b.isKinematic=true;var box=g.AddComponent<BoxCollider>();box.size=new Vector3(1.4f,.8f,2.4f);box.center=new Vector3(0,.25f,0);box.sharedMaterial=contact;var t=g.AddComponent<CheeseTruck>();t.match=m;t.index=i;t.body=b;var visual=HockeyAuthoring.TruckGeometry(g.transform,2.5f);t.paint=visual.GetComponentsInChildren<MeshRenderer>().First(r=>r.name=="Cab");var friction=AssetDatabase.LoadAssetAtPath<FrictionPreset>("Assets/NWH/WheelController/Resources/Wheel Controller 3D/Defaults/DefaultFrictionPreset.asset");t.wheels=new WheelController[4];for(int w=0;w<4;w++){var wg=new GameObject("NWH wheel "+w);wg.layer=2;wg.transform.SetParent(g.transform,false);wg.transform.localPosition=new Vector3(w%2==0?-.6f:.6f,.02f,w<2?.86f:-.86f);var wheel=wg.AddComponent<WheelController>();wheel.wheel.radius=.3f;wheel.wheel.width=.2f;wheel.wheel.mass=1.2f;wheel.spring.maxLength=.13f;wheel.spring.maxForce=650;wheel.damper.bumpRate=wheel.damper.reboundRate=800;wheel.rollingResistanceTorque=.03f;wheel.FrictionPreset=friction;wheel.frictionSubsteps=6;wheel.forceApplicationPointDistance=.08f;wheel.layerMask=1;t.wheels[w]=wheel;var tire=Primitive("Rubber tire",PrimitiveType.Cylinder,g.transform,wg.transform.localPosition,new Vector3(.6f,.1f,.6f),dark);tire.transform.localRotation=Quaternion.Euler(0,0,90);}
  var mark=new GameObject("Scoring participant marker").AddComponent<TextMeshPro>();mark.transform.SetParent(g.transform,false);mark.transform.localPosition=new Vector3(0,1.8f,0);mark.text="P"+(i+1);mark.font=TMP_Settings.defaultFontAsset;mark.fontSize=4;mark.alignment=TextAlignmentOptions.Center;mark.rectTransform.sizeDelta=new Vector2(3,1);t.marker=mark.transform;t.engine=Loop(g,"Assets/NWH/Vehicle Physics 2/Sound/Engine/Running/EngineRunning - Truck4.wav");t.skid=Loop(g,"Assets/NWH/Vehicle Physics 2/Sound/GroundNoise/AsphaltSkidNoise.wav");t.splash=Effect("Mud splash",g.transform,Mat("Mud spray",new Color(.16f,.1f,.05f)),28,1.5f,.5f);var main=t.splash.main;main.loop=true;var em=t.splash.emission;em.rateOverTime=12;em.SetBursts(Array.Empty<ParticleSystem.Burst>());t.tracks=new TrailRenderer[2];for(int k=0;k<2;k++){var track=new GameObject("Muddy tire track").AddComponent<TrailRenderer>();track.transform.SetParent(g.transform,false);track.transform.localPosition=new Vector3(k==0?-.6f:.6f,-.15f,-.8f);track.sharedMaterial=dark;track.time=4;track.startWidth=.18f;track.endWidth=.1f;track.emitting=false;t.tracks[k]=track;}g.transform.position=CheeseRules.Surface((i%4-1.5f)*8,8-(i/4)*7,1.2f);return t;
 }
 static AudioSource Loop(GameObject g,string path){var s=g.AddComponent<AudioSource>();s.clip=AssetDatabase.LoadAssetAtPath<AudioClip>(path);s.loop=true;s.playOnAwake=false;s.volume=0;s.spatialBlend=0;return s;}
 static ParticleSystem Effect(string n,Transform parent,Material mat,int count,float speed,float life){var g=new GameObject(n);g.transform.SetParent(parent,false);var ps=g.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.playOnAwake=false;main.loop=false;main.duration=life;main.startLifetime=life;main.startSpeed=speed;main.startSize=n.StartsWith("Pooled")?1.3f:.15f;main.startColor=n.StartsWith("Pooled")?new ParticleSystem.MinMaxGradient(new Color(1,.35f,.03f),new Color(.1f,.09f,.08f)):new ParticleSystem.MinMaxGradient(new Color(.2f,.12f,.06f));main.gravityModifier=.4f;main.maxParticles=count;main.simulationSpace=ParticleSystemSimulationSpace.World;var em=ps.emission;em.rateOverTime=0;em.SetBursts(new[]{new ParticleSystem.Burst(0,(short)count)});var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Sphere;shape.radius=.8f;ps.GetComponent<ParticleSystemRenderer>().sharedMaterial=mat;return ps;}
 static Mesh WheelMesh(){string p=Root+"Materials/Convex cheese cylinder.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(p);if(mesh!=null)return mesh;var temp=GameObject.CreatePrimitive(PrimitiveType.Cylinder);mesh=UnityEngine.Object.Instantiate(temp.GetComponent<MeshFilter>().sharedMesh);mesh.name="Cheese wheel convex cylinder";var v=mesh.vertices;for(int i=0;i<v.Length;i++)v[i]=Vector3.Scale(v[i],new Vector3(3.6f,.55f,3.6f));mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,p);UnityEngine.Object.DestroyImmediate(temp);return mesh;}
 public static void UpgradeFront(){var scene=EditorSceneManager.OpenScene(SportsBuilder.FrontScene);var f=UnityEngine.Object.FindAnyObjectByType<SportsFrontEnd>();var page=f.pages[1].transform;var card=page.Find("CHEESE Sport Card");if(card==null){card=UnityEngine.Object.Instantiate(page.Find("CORNHOLE Sport Card").gameObject,page).transform;card.name="CHEESE Sport Card";SportsUIAuthoring.Button(page,"PLAY","cheese",Vector2.zero,new Vector2(300,50));}string[] names={"BILLIARDS","HOCKEY","BOWLING","AIR HOCKEY","WALLBALL","CORNHOLE","CHEESE"};string[] keys={"billiards","hockey","bowling","airhockey","wallball","cornhole","cheese"};for(int i=0;i<7;i++){float x=(i%4-1.5f)*345,y=i<4?105:-175;var r=page.Find(names[i]+" Sport Card").GetComponent<RectTransform>();r.sizeDelta=new Vector2(330,260);r.anchoredPosition=new Vector2(x,y);var title=r.Find("Sport").GetComponent<TMP_Text>();title.rectTransform.sizeDelta=new Vector2(310,90);title.rectTransform.anchoredPosition=new Vector2(0,80);title.fontSizeMax=i==6?25:28;title.fontSizeMin=21;if(i==6)title.text="HARDCORE TRUCK\nCHEESE ROLLING";var d=r.Find("Description").GetComponent<TMP_Text>();d.rectTransform.sizeDelta=new Vector2(305,100);d.rectTransform.anchoredPosition=new Vector2(0,-5);d.fontSizeMax=20;d.fontSizeMin=17;if(i==6)d.text="Catch the physical cheese.\n12 chaotic background trucks.\nFirst to five · 1–4 players.";foreach(var a in page.GetComponentsInChildren<SportsMenuAction>(true))if(a.action==keys[i]||i==0&&a.action=="practice"){var b=a.GetComponent<RectTransform>();b.sizeDelta=new Vector2(i==0?150:300,48);b.anchoredPosition=new Vector2(x+(i==0?(a.action=="practice"?78:-78):0),y-95);a.button.normalTextObj.rectTransform.sizeDelta=b.sizeDelta-new Vector2(8,6);a.button.normalTextObj.fontSizeMax=20;}}
  f.pages[0].transform.Find("Collection").GetComponent<TMP_Text>().text="BILLIARDS · ICE HOCKEY · BOWLING · AIR HOCKEY\nWALLBALL · CORNHOLE · HARDCORE TRUCK CHEESE ROLLING";page.Find("Subtitle").GetComponent<TMP_Text>().text="Seven sports · Offline local play";EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("CHEESE_FRONT_INTEGRATED");SportsExpansionFront.Upgrade();}
 public static void Validate(){CheeseFixtures.Run();var scene=EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<CheeseMatch>();if(m==null||m.trucks.Length!=16||m.sheep.Length<24||m.cameras.Length!=4||m.scenery==null||m.scenery.trees.Length!=14||m.menus.countdowns.Length!=4||m.scenery.props.Length!=40||m.look==null||m.look.pipeline==null||m.weather.vendor==null||m.weather.precipitation==null)throw new Exception("Cheese scene references incomplete");foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Cheese missing script "+t.name);if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Cheese requires exactly one listener");Debug.Log("CHEESE_SAVED_SCENE_VALIDATED sheep_model=Haberdashery_SheepV5");}
 public static void PruneUnusedOwnedAssets(){var used=AssetDatabase.GetDependencies(Scene,true);foreach(var path in AssetDatabase.FindAssets("",new[]{Root+"Materials",Root+"Rendering"}).Select(AssetDatabase.GUIDToAssetPath)){if(AssetDatabase.IsValidFolder(path)||used.Contains(path))continue;string name=Path.GetFileNameWithoutExtension(path);if(path.StartsWith(Root+"Rendering/")||name.StartsWith("Hill terrain ")||name.StartsWith("Race daylight profile "))AssetDatabase.DeleteAsset(path);}AssetDatabase.SaveAssets();}
 public static void FinalizeBuild(){PruneUnusedOwnedAssets();SportsBuilder.Build();}
 public static void CreateBuild(){Create();SportsBuilder.Build();}
